# -*- coding: utf-8 -*-
"""Make the HTML generated by pygbag responsive to phone touchscreens."""
from pathlib import Path
import re
import sys


def patch_html(path):
    html_path = Path(path)
    html = html_path.read_text(encoding='utf-8')
    if 'data-mobile-controls-4546b' in html:
        return
    if not re.search(r'</head\s*>', html, flags=re.I):
        raise ValueError('pygbag page is missing closing </head>')
    addition = """
<!-- data-mobile-controls-4546b -->
<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover">
<meta name="apple-mobile-web-app-capable" content="yes">
<meta name="theme-color" content="#061b2c">
<style>
  html, body { margin:0; width:100%; min-height:100%; overflow:hidden;
               overscroll-behavior:none; background:#061b2c; }
  html { -webkit-text-size-adjust:100%; touch-action:none; }
  body { overscroll-behavior:none; }
  canvas, canvas#canvas {
      touch-action:none !important; -ms-touch-action:none !important;
      -webkit-user-select:none; user-select:none;
      width:min(100vw, 100vh) !important;
      height:min(100vw, 100vh) !important;
      width:min(100vw, 100dvh) !important;
      height:min(100vw, 100dvh) !important;
      max-width:100vw !important; max-height:100dvh !important;
      object-fit:contain !important;
  }
</style>
<script>
  /* Keep touches inside the canvas; allow SDL/pygame to receive all fingers.
     Do not preventDefault on touch events: pygame SDL uses them as input. */
  document.addEventListener('contextmenu', function (e) {
    if (e.target instanceof HTMLCanvasElement) e.preventDefault();
  });
</script>
"""
    html = re.sub(r'</head\s*>', lambda m: addition + '\n' + m.group(0),
                  html, count=1, flags=re.I)
    html_path.write_text(html, encoding='utf-8')

if __name__ == '__main__':
    if len(sys.argv) != 2:
        raise SystemExit('usage: python patch_mobile_html.py game/build/web/index.html')
    patch_html(sys.argv[1])
